def preencher_alugueis_existentes(apps, schema_editor):
    """
    Boxes alugados antes desta versão: vencimento no dia 5 (pode ser alterado
    pelo site) e início hoje. O comprovante que já existia vira a mensalidade
    paga do mês atual.
    """
    from boxes.cobranca import data_vencimento

    Box = apps.get_model("boxes", "Box")
    Mensalidade = apps.get_model("boxes", "Mensalidade")
    hoje = timezone.localdate()
    competencia = hoje.replace(day=1)
    for box in Box.objects.filter(cliente__isnull=False):
        box.dia_vencimento = 5
        box.alugado_em = hoje
        box.save(update_fields=["dia_vencimento", "alugado_em"])
        Mensalidade.objects.create(
            box=box, cliente_id=box.cliente_id, competencia=competencia,
            vencimento=data_vencimento(competencia, 5), valor=box.valor,
            pago_em=hoje, comprovante=box.anexo_pagamento,
        )


